class FileCloser {
    FileHandle handle_;
public:
    // Resource Acquisition Is Initialization (RAII)
    explicit FileCloser(const char* filename)
        : handle_(open_file(filename)) {}

    // Resource released upon scope exit/exception
    ~FileCloser() {
        if (handle_.is_valid()) {
            close_file(handle_);
        }
    }
    // Rule of Zero/Five: Must manage ownership transfer
    FileCloser(const FileCloser&) = delete;
    FileCloser& operator=(const FileCloser&) = delete;
};

void process_data() {
    FileCloser safe_file("data.txt");
